from collections import deque

def traversal(node, mode):
    if mode not in ("pre", "in", "post"):
        raise ValueError("Mode tidak dikenal")
    hasil = []
    def kunjungi(saat_ini):
        if saat_ini is None:
            return
        if mode == "pre":
            hasil.append(saat_ini["nilai"])
        kunjungi(saat_ini["kiri"])
        if mode == "in":
            hasil.append(saat_ini["nilai"])
        kunjungi(saat_ini["kanan"])
        if mode == "post":
            hasil.append(saat_ini["nilai"])
    kunjungi(node)
    return hasil

def level_order(root):
    hasil = []
    antrean = deque([root]) if root is not None else deque()
    while antrean:
        node = antrean.popleft()
        hasil.append(node["nilai"])
        for sisi in ("kiri", "kanan"):
            if node[sisi] is not None:
                antrean.append(node[sisi])
    return hasil

