def selection_sort(data):
    hasil = data.copy()
    for i in range(len(hasil)):
        terkecil = i
        for j in range(i + 1, len(hasil)):
            if hasil[j] < hasil[terkecil]:
                terkecil = j
        hasil[i], hasil[terkecil] = hasil[terkecil], hasil[i]
    return hasil

def merge_sort(data):
    if len(data) <= 1:
        return data.copy()
    tengah = len(data) // 2
    kiri = merge_sort(data[:tengah])
    kanan = merge_sort(data[tengah:])
    hasil, i, j = [], 0, 0
    while i < len(kiri) and j < len(kanan):
        if kiri[i] <= kanan[j]:
            hasil.append(kiri[i])
            i += 1
        else:
            hasil.append(kanan[j])
            j += 1
    hasil.extend(kiri[i:])
    hasil.extend(kanan[j:])
    return hasil

