def buat_tabel(kapasitas):
    if type(kapasitas) is not int or kapasitas <= 0:
        raise ValueError("Kapasitas harus integer positif")
    bucket = []
    for nomor in range(kapasitas):
        bucket.append([])
    return {"bucket": bucket, "jumlah": 0}

def indeks(tabel, key):
    if not isinstance(key, str):
        raise TypeError("Key latihan harus string")
    total = 0
    for karakter in key:
        total += ord(karakter)
    return total % len(tabel["bucket"])

def simpan(tabel, key, nilai):
    bucket = tabel["bucket"][indeks(tabel, key)]
    for pasangan in bucket:
        if pasangan[0] == key:
            pasangan[1] = nilai
            return
    bucket.append([key, nilai])
    tabel["jumlah"] += 1

def ambil(tabel, key, bawaan=None):
    for pasangan in tabel["bucket"][indeks(tabel, key)]:
        if pasangan[0] == key:
            return pasangan[1]
    return bawaan

