        return {"nilai": nilai, "kiri": None, "kanan": None}
    if nilai < root["nilai"]:
        root["kiri"] = tambah(root["kiri"], nilai)
    elif nilai > root["nilai"]:
        root["kanan"] = tambah(root["kanan"], nilai)
    return root

def hapus(root, target):
    if root is None:
        return None
    if target < root["nilai"]:
        root["kiri"] = hapus(root["kiri"], target)
    elif target > root["nilai"]:
        root["kanan"] = hapus(root["kanan"], target)
    else:
        if root["kiri"] is None:
            return root["kanan"]
        if root["kanan"] is None:
            return root["kiri"]
        successor = root["kanan"]
        while successor["kiri"] is not None:
            successor = successor["kiri"]
        root["nilai"] = successor["nilai"]
        root["kanan"] = hapus(root["kanan"], successor["nilai"])
    return root

def inorder(root):
    if root is None:
        return []
    return inorder(root["kiri"]) + [root["nilai"]] + inorder(root["kanan"])

