def tinggi(node):
    return 0 if node is None else node["tinggi"]

def perbarui(node):
    node["tinggi"] = 1 + max(tinggi(node["kiri"]), tinggi(node["kanan"]))

def rotasi_kanan(y):
    x = y["kiri"]
    tengah = x["kanan"]
    x["kanan"] = y
    y["kiri"] = tengah
    perbarui(y)
    perbarui(x)
    return x

def rotasi_kiri(x):
    y = x["kanan"]
    tengah = y["kiri"]
    y["kiri"] = x
    x["kanan"] = tengah
    perbarui(x)
    perbarui(y)
    return y

def tambah(root, nilai):
    if root is None:
        return {"nilai": nilai, "kiri": None, "kanan": None, "tinggi": 1}
    if nilai < root["nilai"]:
        root["kiri"] = tambah(root["kiri"], nilai)
    elif nilai > root["nilai"]:
        root["kanan"] = tambah(root["kanan"], nilai)
    else:
        return root
    perbarui(root)
    balance = tinggi(root["kiri"]) - tinggi(root["kanan"])
    if balance > 1:
        if nilai > root["kiri"]["nilai"]:
            root["kiri"] = rotasi_kiri(root["kiri"])
        return rotasi_kanan(root)
    if balance < -1:
        if nilai < root["kanan"]["nilai"]:
            root["kanan"] = rotasi_kanan(root["kanan"])
        return rotasi_kiri(root)
    return root

