import heapq
from itertools import count
from math import inf

def validasi_graph(graph):
    if not isinstance(graph, dict):
        raise ValueError("Graph harus dictionary")
    for node, tetangga in graph.items():
        if not isinstance(node, str) or not node or not isinstance(tetangga, dict):
            raise ValueError("Node harus teks dan tetangga harus dictionary")
        for tujuan, bobot in tetangga.items():
            if tujuan not in graph:
                raise ValueError("Tetangga belum didaftarkan sebagai node")
            if type(bobot) is not int or bobot < 0:
                raise ValueError("Bobot latihan harus integer nonnegatif")

def dijkstra(graph, awal):
    validasi_graph(graph)
    if not isinstance(awal, str) or awal not in graph:
        raise ValueError("Node awal tidak ada")
    jarak, parent = {}, {}
    for node in graph:
        jarak[node] = inf
        parent[node] = None
    jarak[awal] = 0
    urutan = count()
    heap = [(0, next(urutan), awal)]
    while heap:
        biaya, nomor, node = heapq.heappop(heap)
        if biaya != jarak[node]:
            continue
        for tujuan, bobot in graph[node].items():
            calon = biaya + bobot
            if calon < jarak[tujuan]:
                jarak[tujuan] = calon
                parent[tujuan] = node
                heapq.heappush(heap, (calon, next(urutan), tujuan))
    return jarak, parent

