from collections import deque

def urutan_tugas(graph):
    indegree = {node: 0 for node in graph}
    for node in graph:
        for tujuan in graph[node]:
            if tujuan not in graph:
                raise ValueError("Tetangga belum didaftarkan")
            indegree[tujuan] += 1
    siap = deque(node for node in graph if indegree[node] == 0)
    hasil = []
    while siap:
        node = siap.popleft()
        hasil.append(node)
        for tujuan in graph[node]:
            indegree[tujuan] -= 1
            if indegree[tujuan] == 0:
                siap.append(tujuan)
    if len(hasil) != len(graph):
        raise ValueError("Graph mengandung siklus")
    return hasil

