def buat_kelompok(items):
    parent, ukuran = {}, {}
    for item in items:
        parent[item] = item
        ukuran[item] = 1
    return {"parent": parent, "ukuran": ukuran}

def find(state, item):
    if item not in state["parent"]:
        raise KeyError("ID belum didaftarkan")
    while state["parent"][item] != item:
        state["parent"][item] = state["parent"][state["parent"][item]]
        item = state["parent"][item]
    return item

def union(state, a, b):
    ra, rb = find(state, a), find(state, b)
    if ra == rb:
        return False
    if state["ukuran"][ra] < state["ukuran"][rb]:
        ra, rb = rb, ra
    state["parent"][rb] = ra
    state["ukuran"][ra] += state["ukuran"][rb]
    return True

