def saran(root, prefix, limit=5):
    if not isinstance(prefix, str):
        raise ValueError("Prefix harus teks")
    if type(limit) is not int or limit < 0:
        raise ValueError("Limit harus integer tidak negatif")
    node = root
    for karakter in prefix.strip().casefold():
        if karakter not in node["anak"]:
            return []
        node = node["anak"][karakter]
    hasil, stack = [], [node]
    while stack and len(hasil) < limit:
        saat_ini = stack.pop()
        if saat_ini["nama"] is not None:
            hasil.append(saat_ini["nama"])
        for karakter in reversed(sorted(saat_ini["anak"])):
            stack.append(saat_ini["anak"][karakter])
    return hasil

