    return jarak, parent

def rute_terpendek(graph, awal, tujuan):
    jarak, parent = dijkstra(graph, awal)
    if not isinstance(tujuan, str) or tujuan not in graph:
        raise ValueError("Node tujuan tidak ada")
    if jarak[tujuan] == inf:
        return None
    jalur, node = [], tujuan
    while node is not None:
        jalur.append(node)
        node = parent[node]
    jalur.reverse()
    return {"jalur": jalur, "biaya": jarak[tujuan]}

graph = {"A": {"B": 4, "C": 1}, "B": {"D": 1},
         "C": {"B": 2, "D": 5}, "D": {}, "E": {}}
hasil = rute_terpendek(graph, "A", "D")
print("Jalur:", " -> ".join(hasil["jalur"]))
print("Biaya:", hasil["biaya"])
print("A ke E:", rute_terpendek(graph, "A", "E"))
print("A ke A:", rute_terpendek(graph, "A", "A"))
